APP_ROLE = "axar_app"


def backfill_sequence() -> None:
    """Existing (v1) events get a sequence in their historical order, and the
    tenant's ``event`` counter continues after it. Runs as the table owner
    (RLS does not apply to the owner)."""
    op.execute("""
        UPDATE outbox_events o SET recorded_seq = x.seq,
               aggregate_type = CASE o.type WHEN 'pos.sale.completed' THEN 'sale'
                                            WHEN 'pos.refund.completed' THEN 'refund' END,
               aggregate_id = COALESCE(o.payload::json->>'sale_id', o.payload::json->>'refund_id'),
               aggregate_version = 1, actor = '{"kind":"system"}'
        FROM (SELECT id, row_number() OVER (PARTITION BY tenant_id ORDER BY occurred_at, id) AS seq
              FROM outbox_events) x
        WHERE o.id = x.id""")
    op.execute("""
        INSERT INTO tenant_counters (tenant_id, name, value)
        SELECT tenant_id, 'event', max(recorded_seq) FROM outbox_events GROUP BY tenant_id
        ON CONFLICT (tenant_id, name) DO UPDATE SET value = EXCLUDED.value""")


def secure_event_tables() -> None:
    policy = "tenant_id = current_setting('app.tenant_id', true)"
    for table in ("event_consumers", "event_inbox", "event_dead_letters"):
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"CREATE POLICY tenant_isolation ON {table} USING ({policy}) WITH CHECK ({policy})")
    grants = [
        f"GRANT SELECT, INSERT, UPDATE ON event_consumers TO {APP_ROLE}",
        f"GRANT SELECT, INSERT ON event_inbox TO {APP_ROLE}",            # dedup records are append-only
        f"GRANT SELECT, INSERT, UPDATE ON event_dead_letters TO {APP_ROLE}",  # resolve, never delete
        f"GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO {APP_ROLE}",
    ]
    body = "; ".join(grants)
    op.execute(f"DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{APP_ROLE}') "
               f"THEN {body}; END IF; END $$")


